void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.getAbstractType(i);
        switch (type.getTag()) {
            case AbstractType.INT:
                stackMapTableEntries.add(new IntegerConstant());
                break;
            case AbstractType.FLOAT:
                stackMapTableEntries.add(new FloatConstant());
                break;
            case AbstractType.LONG:
                stackMapTableEntries.add(new LongConstant());
                break;
            case AbstractType.DOUBLE:
                stackMapTableEntries.add(new DoubleConstant());
                break;
            case AbstractType.NULL:
                stackMapTableEntries.add(new NullConstant());
                break;
            case AbstractType.UNINITIALIZED_THIS:
                stackMapTableEntries.add(new UninitializedThis());
                break;
            case AbstractType.OBJECT:
                stackMapTableEntries.add(new ObjectConstant(type.getTypeDescriptor()));
                break;
            case AbstractType.UNINITIALIZED:
                stackMapTableEntries.add(new Uninitialized(type.getOffset()));
                break;
            default:
                throw new IllegalStateException("Illegal abstract type tag: " + type.getTag());
        }
    }
}

private void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        switch (type) {
            case 0:
                // Null version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(255));
                break;
            case 1:
                // Integer version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(251));
                break;
            case 2:
                // Double version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(252));
                break;
            case 3:
                // Long version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(253));
                break;
            case 4:
                // Float version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(254));
                break;
            case 5:
                // UninitializedThis version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(0));
                break;
            case 6:
                // Object version of T_Object
                stackMapTableEntries.add(new StackMapFrame.Object(1));
                break;
            default:
                throw new Error("Unexpected abstract type: " + type);
        }
    }
}

void putAbstractTypes(int start, int end) {
for (int i = start; i < end; i++) {
stackMapTableEntries.add(new AbstractType(currentFrame.getType(i)));
